# region: shape
def shape(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: fold
def fold(xs):
    return [v * v for v in xs]

# region: emit
def emit(xs):
    return [v * v for v in xs]

# region: render
def render(xs, factor=3):
    return [v * factor for v in xs]

# region: sift
def sift(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: intake
def intake(summary, name='alpha'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return intake(sift(render(emit(fold(shape(raw))))))

