        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'mean': 98.0, 'max': 243, 'label': 'ALPHA'})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 3, 'mean': 12401.0, 'max': 30000, 'label': 'ALPHA'})
